Here's a full React component implementation with a Redux-Toolkit state management system. This example leverages the `createSlice` function from Redux Toolkit to create a simple cart reducer that manages cart items, and a `createAsyncThunk` generator for API requests. It doesn't handle server-side rendering or any complexities, but it's a starting point and can be refined based on your needs.

```jsx
// cartSlice.js (Redux Slice for cart management)
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Helper for parsing JSON API response (if it's not JSON, it's an error)
const parseJSON = (response: any) => response.json().catch(() => Promise.reject(response));

const cartSlice = createSlice({
  name: 'cart',
  initialState: {
    loading: false,
    items: [],
  },
  reducers: {
    addItem(state, action: PayloadAction<{ id: number; quantity: number }>) {
      const existingItem = state.items.find((item) => item.id === action.payload.id);
      if (existingItem) {
        existingItem.quantity += action.payload.quantity;
      } else {
        state.items.push({ id: action.payload.id, quantity: action.payload.quantity });
      }
    },
    removeItem(state, action: PayloadAction<number>) {
      state.items = state.items.filter((item) => item.id!== action.payload);
    },
  },
  extraReducers: (builder) => {
    builder
     .addCase(createGetCartThunk.pending, (state) => {
        state.loading = true;
      })
     .addCase(createGetCartThunk.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload;
      })
     .addCase(createGetCartThunk.rejected, (state) => {
        state.loading = false;
      });
  },
});

// API Calls
const getCart = createAsyncThunk('cart/getCart', async () => {
  const res = await axios.get('https://example.com/api/cart');
  return parseJSON(res);
});

export const createGetCartThunk = getCart;
export default cartSlice.reducer;
```

